Increase setup WNS for module pw_fsm_sync, fixed parameter overrides {}. Preserve exact cycle-by-cycle behavior, clock, synchronous reset, registered latency, valid/ready and all outputs. All initial DUT states are independent arbitrary defined values. All initialization attributes are stripped. Reset is asserted at the first sample, and all outputs are compared from sample2 forever. All later inputs and repeated reset are unconstrained. No extra startup or input assumptions. Keep existing named register/state encodings where possible for the declared auxiliary proof targets. Preserve module name, ports, signedness, priority and default behavior, truncation and parameters. No latches, memories, generated clocks, asynchronous reset, includes, file access, formal assumptions, assertions or undefined outputs. Supply a complete design including required helper modules. Evaluation uses SKY130HD TT25C1.80V, fixed library/mapping and interface constraints. Clock period for sequential cases is 10.0ns. Original-relative area cap is 1102.432320um2. Source and mapped equivalence, STA and electrical checks must pass. Return exactly one JSON object with six string fields candidate_rtl, bottleneck, rewrite, expected_timing_gain, area_or_other_cost, functional_boundaries.
Original reference RTL:
module pw_fsm_sync (
    input clk,
    input rst,
    input start,
    input [7:0] data_in,
    output reg [7:0] data_out,
    output reg done
);


localparam [8:0] S_IDLE  = 9'b000000001;
localparam [8:0] S_START = 9'b000000010;
localparam [8:0] S_READ  = 9'b000000100;
localparam [8:0] S_PROC1 = 9'b000001000;
localparam [8:0] S_PROC2 = 9'b000010000;
localparam [8:0] S_PROC3 = 9'b000100000;
localparam [8:0] S_WAIT  = 9'b001000000;
localparam [8:0] S_DONE  = 9'b010000000;
localparam [8:0] S_ERROR = 9'b100000000;

reg [8:0] state, next_state;


always @(*) begin
    next_state = S_IDLE; // Default
    case (state)
        S_IDLE:  next_state = start ? S_START : S_IDLE;
        S_START: next_state = (data_in[0]) ? S_READ : S_ERROR;
        S_READ:  next_state = (data_in[3:1] == 3'b101) ? S_PROC1 : S_WAIT;
        S_PROC1: next_state = S_PROC2;
        S_PROC2: next_state = (data_in[7]) ? S_PROC3 : S_WAIT;
        S_PROC3: next_state = S_DONE;
        S_WAIT:  next_state = (data_in[4]) ? S_READ : S_WAIT;
        S_DONE:  next_state = S_IDLE;
        S_ERROR: next_state = (data_in[2:0] == 3'b111) ? S_IDLE : S_ERROR;
        default: next_state = S_IDLE;
    endcase
end

always @(*) begin
    {data_out, done} = {8'h00, 1'b0};
    case (state)
        S_READ:  data_out = data_in;
        S_PROC1: data_out = data_in + 8'h01;
        S_PROC2: data_out = data_in << 1;
        S_PROC3: data_out = data_in ^ 8'hFF;
        S_DONE:  {data_out, done} = {data_in, 1'b1};
        S_ERROR: data_out = 8'hEE;
    endcase
end

always @(posedge clk) begin
    if (rst) begin
        state <= S_IDLE;
    end else begin
        state <= next_state;
    end
end

endmodule
